<template><ElConfigProvider namespace="kel"><section class="native-agents"><header><div><h1>Agents <small>{{rows.length}}</small></h1><p>设备连接、能力与证书</p></div><KsButton @click="emit('refresh')">刷新</KsButton><KsButton type="primary" :disabled="!canEdit" @click="emit('enroll')">纳管设备</KsButton></header><div class="filters"><KsInput :modelValue="query" placeholder="Hostname / Asset ID / Agent ID" @update:modelValue="v=>emit('filter','q',v)"/><select :value="status" @change="emit('filter','status',value($event))"><option value="all">所有状态</option><option v-for="state in ['ONLINE','OFFLINE','PENDING_VERIFICATION','QUARANTINED','REVOKED']" :key="state">{{state}}</option></select><select :value="version" @change="emit('filter','version',value($event))"><option value="">所有版本</option><option v-for="v in [...new Set(rows.map(a=>a.version))]" :key="v">{{v}}</option></select><select :value="capability" @change="emit('filter','capability',value($event))"><option value="">所有能力</option><option v-for="v in [...new Set(rows.flatMap(a=>a.capabilities))]" :key="v">{{v}}</option></select></div><div v-if="checked.length" class="filters"><b>{{checked.length}} selected</b><KsButton size="small" @click="emit('health')">检查连接健康</KsButton><KsButton size="small" @click="emit('checked',[])">清除</KsButton></div><p v-if="error" class="error" role="alert">{{error}}</p><KsDataTable :data="pagedAgents" :total="visible.length" v-model:currentPage="page" v-model:pageSize="pageSize" :selectable="true" rowKey="id" :loading="loading" @selection-change="rows=>emit('checked',rows.map(r=>r.id))" @row-click="a=>emit('select',a.id)"><KsTableColumn label="设备 / Agent" minWidth="230"><template #default="{row}"><b>{{row.identity.hostname||'unknown'}}</b><small>{{row.id}}</small></template></KsTableColumn><KsTableColumn prop="asset_id" label="CMDB 资产" minWidth="170"/><KsTableColumn prop="version" label="版本" width="90"/><KsTableColumn label="状态" width="160"><template #default="{row}"><span :class="['agent-state',state(row).toLowerCase()]">{{state(row)}}</span><small>{{health[row.id]}}</small></template></KsTableColumn><KsTableColumn label="能力" minWidth="180"><template #default="{row}"><span :title="row.capabilities.join('\n')">{{row.capabilities.slice(0,3).join(' · ')}}</span></template></KsTableColumn><KsTableColumn label="最近心跳" minWidth="165"><template #default="{row}">{{date(row.last_heartbeat)}}</template></KsTableColumn><KsTableColumn label="证书到期" minWidth="165"><template #default="{row}">{{date(row.certificate_expires_at)}}</template></KsTableColumn></KsDataTable>
<div v-if="selected" class="drawer-mask" @click.self="emit('select','')"><aside class="agent-drawer"><div class="drawer-heading"><div><small>AGENT DETAIL</small><h2>{{selected.identity.hostname||selected.id}}</h2></div><KsButton size="small" @click="emit('select','')">关闭</KsButton></div><nav><button v-for="t in ['Overview','Capabilities','Tasks','Connection','Certificate','Logs / Audit']" :key="t" :class="{active:tab===t}" @click="emit('tab',t)">{{t}}</button></nav><template v-if="tab==='Overview'"><dl><dt>资产</dt><dd><button class="link" @click="emit('navigate','/cmdb?asset='+encodeURIComponent(selected.asset_id))">{{selected.asset_id}} →</button></dd><dt>项目</dt><dd>{{selected.project_id}}</dd><dt>OS</dt><dd>{{selected.identity.os||'未采集'}}</dd><dt>版本</dt><dd>{{selected.version}}</dd><dt>状态</dt><dd>{{state(selected)}}</dd></dl><div class="actions"><KsButton v-for="a in ['approve','quarantine','revoke']" :key="a" :disabled="!canEdit||selected.state==='revoked'||a==='approve'&&selected.state!=='pending_verification'" @click="emit('action',a)">{{a==='approve'?'批准身份':a==='quarantine'?'隔离':'撤销'}}</KsButton></div></template><div v-else-if="tab==='Capabilities'" class="capabilities"><code v-for="c in selected.capabilities" :key="c">{{c}}</code></div><dl v-else-if="tab==='Connection'"><dt>连接</dt><dd>{{state(selected)}}</dd><dt>协议</dt><dd>Outbound gRPC · mTLS</dd><dt>最近心跳</dt><dd>{{date(selected.last_heartbeat)}}</dd><dt>机器身份</dt><dd>{{selected.identity.machine_id||'unknown'}}</dd></dl><dl v-else-if="tab==='Certificate'"><dt>序列号</dt><dd>{{selected.certificate_serial||'unknown'}}</dd><dt>到期时间</dt><dd>{{date(selected.certificate_expires_at)}}</dd><dt>信任</dt><dd>Keel Agent CA / mTLS</dd><dt>自动轮换</dt><dd>{{selected.capabilities.includes('certificate.renew')?'Agent已启用续期；空闲时通过mTLS申请并切换新证书':'当前Agent未启用证书自动轮换'}}</dd></dl><KsDataTable v-else :data="pagedHistory" :total="history.length" v-model:currentPage="historyPage" v-model:pageSize="historySize" :selectable="false" rowKey="id" :loading="historyLoading"><KsTableColumn v-if="tab==='Tasks'" prop="state" label="State"/><KsTableColumn v-if="tab==='Tasks'" label="Execution"><template #default="{row}"><button class="link" @click="emit('navigate','/flows/executions/'+row.execution_id)">{{row.execution_id?.slice(0,12)}} →</button></template></KsTableColumn><KsTableColumn v-if="tab!=='Tasks'" prop="action" label="Action"/><KsTableColumn v-if="tab!=='Tasks'" prop="actor" label="Actor"/><KsTableColumn label="时间"><template #default="{row}">{{date(row.updated_at||row.created_at)}}</template></KsTableColumn></KsDataTable><section v-if="action" class="confirm"><h3>{{action}} · {{selected.identity.hostname}}</h3><label>操作理由<textarea :value="reason" @input="emit('reason',value($event))"/></label><KsButton :disabled="reason.trim().length<5||busy" @click="emit('confirm')">确认操作</KsButton></section></aside></div>
<KsDialog :modelValue="enrollOpen" :teleported="false" :appendToBody="false" title="纳管设备" width="950px" @update:modelValue="v=>{if(!v&&!installing)emit('closeEnroll')}"><section class="enroll"><div class="filters"><KsInput :modelValue="targetSearch" placeholder="搜索 CMDB 设备" @update:modelValue="v=>emit('targetSearch',v)"/><label>版本<select :value="installVersion" :disabled="installing" @change="emit('installVersion',value($event))"><option v-for="v in caps?.agent_versions||['0.2.0']" :key="v">{{v}}</option></select></label><span>{{installIds.length}} selected</span></div><div class="install-targets"><label v-for="target in targets" :key="target.id"><input type="checkbox" :checked="installIds.includes(target.id)" :disabled="installing" @change="emit('installIds',($event.target as HTMLInputElement).checked?[...installIds,target.id]:installIds.filter(id=>id!==target.id))"/><span><b>{{target.name}}</b><small>{{target.id}}</small></span><button v-if="!target.ssh_profile_id" class="link" @click="emit('navigate','/admin/ssh-trust')">配置 SSH Trust →</button><code>{{installResults[target.id]?.state||'NOT_STARTED'}}</code><small>{{installResults[target.id]?.message}}</small></label></div><p v-if="!caps?.bootstrap_ready" class="warning">尚未配置安装包、公开 TLS 地址或网关，自动安装不可用。可对单台设备生成手动注册 Token。</p><div class="actions"><KsButton :disabled="installIds.length!==1||installing||tokenBusy" @click="emit('token')">手动注册 Token</KsButton><KsButton type="primary" :disabled="!caps?.bootstrap_ready||!installIds.length||installing||installIds.some(id=>!targets.find(t=>t.id===id)?.ssh_profile_id)" @click="emit('install')">{{installing?'正在创建…':'创建 '+installIds.length+' 台安装批次'}}</KsButton></div><section v-if="jobs?.length" class="installation-jobs"><h3>安装批次 · 服务端保存进度</h3><article v-for="job in jobs" :key="job.id"><div><b>{{job.state}}</b><code>{{job.id.slice(0,12)}}</code><span>{{job.items.filter(i=>i.state==='SUCCEEDED').length}} / {{job.items.length}} 安装请求完成</span></div><small>成功项仍需 Agent 注册与身份核验。取消只停止未派发项；UNKNOWN 不会自动重试。</small><div class="actions"><KsButton v-if="['PENDING','RUNNING'].includes(job.state)" size="small" :disabled="!canEdit||jobBusy" @click="emit('jobAction',job.id,'pause')">暂停后续项</KsButton><KsButton v-if="job.state==='PAUSED'" size="small" :disabled="!canEdit||jobBusy" @click="emit('jobAction',job.id,'resume')">继续</KsButton><KsButton v-if="['PARTIAL_FAILURE','PAUSED'].includes(job.state)&&job.items.some(i=>i.state==='BLOCKED')" size="small" :disabled="!canEdit||jobBusy" @click="emit('jobAction',job.id,'retry-blocked')">重试阻断项</KsButton><KsButton v-if="job.items.some(i=>i.state==='UNKNOWN')" size="small" :disabled="!canEdit||jobBusy" @click="emit('jobAction',job.id,'reconcile')">从注册表对账</KsButton><KsButton v-if="!['COMPLETED','CANCELLED'].includes(job.state)" size="small" :disabled="!canEdit||jobBusy" @click="emit('jobAction',job.id,'cancel')">取消未派发项</KsButton></div><details><summary>逐台结果</summary><div v-for="item in job.items" :key="item.ordinal" class="job-item"><code>{{item.asset_id}}</code><span>{{item.state}}</span><small>{{item.error_code||item.result.state||'—'}}</small></div></details></article></section><div v-if="token" class="token"><b>一次性 Token · {{token.asset_id}}</b><small>有效至 {{date(token.expires_at)}}，不写入日志或命令参数。</small><pre>{{token.token}}</pre><code>keel-agent --token-file /run/keel-agent/enrollment-token --state-dir /var/lib/keel-agent</code></div><p v-if="error" class="error">{{error}}</p></section></KsDialog>
</section></ElConfigProvider></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import KsDataTable from '../../vendor/kestra/design-system/components/Data/KsDataTable/KsDataTable.vue';import KsTableColumn from '../../vendor/kestra/design-system/components/Data/KsTable/KsTableColumn.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';
const props=defineProps<{rows:any[];query:string;status:string;version:string;capability:string;checked:string[];health:Record<string,string>;selectedId:string;tab:string;history:any[];historyLoading:boolean;loading:boolean;error:string;canEdit:boolean;busy:boolean;action:string;reason:string;enrollOpen:boolean;targets:any[];caps:any;installIds:string[];installVersion:string;installing:boolean;installResults:Record<string,any>;targetSearch:string;token:any;tokenBusy:boolean;jobs?:any[];jobBusy:boolean}>(),emit=defineEmits(['refresh','enroll','filter','checked','health','select','navigate','tab','action','reason','confirm','closeEnroll','targetSearch','installVersion','installIds','token','install','jobAction']);
const page=ref(1),pageSize=ref(25),historyPage=ref(1),historySize=ref(10);watch(()=>[props.query,props.status,props.version,props.capability],()=>page.value=1);watch(()=>[props.selectedId,props.tab],()=>historyPage.value=1);watch(()=>props.rows.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(props.rows.length/pageSize.value)))});
const value=(e:Event)=>(e.target as HTMLInputElement).value,state=(a:any)=>a.state==='enrolled'?(a.online?'ONLINE':'OFFLINE'):a.state.toUpperCase(),date=(v:any)=>v?new Date(v).toLocaleString():'unknown';
const selected=computed(()=>props.rows.find(a=>a.id===props.selectedId)),visible=computed(()=>props.rows.filter(a=>(props.status==='all'||state(a)===props.status)&&(!props.version||a.version===props.version)&&(!props.capability||a.capabilities.includes(props.capability))&&[a.id,a.asset_id,a.identity.hostname].join(' ').toLowerCase().includes(props.query.toLowerCase())));
const pagedAgents=computed(()=>visible.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value)),pagedHistory=computed(()=>props.history.slice((historyPage.value-1)*historySize.value,historyPage.value*historySize.value));
</script>
<style scoped>.native-agents{font:12px var(--ks-font-family-sans);color:var(--ks-text-primary);background:var(--ks-bg-surface);min-height:650px}header{display:flex;align-items:center;gap:10px;padding:18px 20px;border-bottom:1px solid var(--ks-border-default)}header>div{margin-right:auto}h1{font-size:24px;margin:0}h1 small{font-size:12px;font-weight:400;margin-left:8px}header p{font-size:11px;color:var(--ks-text-secondary);margin:5px 0 0}.filters,.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 18px}.filters>.kel-input{max-width:350px}.filters select{padding:6px;border:1px solid var(--ks-border-default);background:var(--ks-bg-input);color:inherit;border-radius:4px;font-size:11px}small{display:block;color:var(--ks-text-secondary);font-size:10px;margin-top:5px}.agent-state{font-size:10px;border:1px solid var(--ks-border-default);border-radius:4px;padding:4px 6px}.agent-state.online{color:#43b89b}.agent-state.offline,.warning{color:#c4a16d}.error{color:#df7490;padding:10px 18px}.drawer-mask{position:fixed;inset:0;background:#0007;z-index:65;display:flex;justify-content:flex-end}.agent-drawer{width:650px;max-width:90vw;overflow:auto;background:var(--ks-bg-surface);padding:22px;box-shadow:-10px 0 40px #0003}.drawer-heading{display:flex;align-items:center;justify-content:space-between}.drawer-heading h2{font-size:20px;margin:8px 0 16px}.agent-drawer nav{display:flex;gap:16px;flex-wrap:wrap;border-block:1px solid var(--ks-border-default);padding:12px 0}.agent-drawer nav button{font-size:11px;color:var(--ks-text-secondary)}.agent-drawer nav button.active,.link{color:var(--ks-text-link)}dl{display:grid;grid-template-columns:110px 1fr;gap:14px;font-size:12px;margin:25px 0}dt{color:var(--ks-text-secondary)}dd{margin:0;overflow-wrap:anywhere}.capabilities{display:grid;gap:10px;padding:20px 0}.capabilities code{padding:10px;background:var(--ks-bg-base)}.confirm{padding:14px;border:1px solid var(--ks-border-default);margin-top:20px}.confirm textarea{display:block;width:100%;background:var(--ks-bg-input);color:inherit;border:1px solid var(--ks-border-default);min-height:70px;margin:12px 0}.install-targets{max-height:340px;overflow:auto}.install-targets>label{display:flex;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid var(--ks-border-default)}.install-targets>label>span{flex:1}.install-targets code{font-size:10px}.warning{font-size:11px;line-height:1.7}.token{margin-top:18px;background:var(--ks-bg-base);padding:14px}.token pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}.token code{font-size:10px}.installation-jobs{margin-top:20px;border-top:1px solid var(--ks-border-default)}.installation-jobs>article{border-bottom:1px solid var(--ks-border-default);padding:14px 0}.installation-jobs>article>div{display:flex;align-items:center;gap:14px;font-size:11px}.job-item{display:flex;align-items:center;gap:12px;padding:8px 0;font-size:11px}.enroll .actions{padding-inline:0}</style>
